CREATE OR REPLACE FUNCTION public.agent_request_approval(p_job uuid, p_lease uuid, p_offer uuid, p_expected_round integer, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
